/*
 * graph_algorithms.h — the algorithm library behind the unified Graph handle.
 *
 * GENERATED by tools/gen_graph_algorithms.py from list_algorithms.h; do not edit
 * by hand (the graph-building functions at the end live in src/graph_build.c).
 *
 * Each function runs on whichever representation the graph currently uses and
 * tells the adaptive observer what kind of work it did, so the library keeps
 * choosing the cheaper representation for the way you really use it.  Results
 * of these functions are not cached.  The contracts (argument meaning, array
 * sizes, which codes are returned) are those of list_algorithms.h /
 * matrix_algorithms.h; complexity notes below quote the list implementation.
 *
 * Failures: functions returning GraphStatus return the code directly; the
 * bool / size_t / double ones record it for graph_last_error().
 * A NULL graph gives GRAPH_ERR_INVALID_ARGUMENT.
 *
 * Link with -lm.
 */

#ifndef GRAPH_ALGORITHMS_H
#define GRAPH_ALGORITHMS_H

#include <stdbool.h>
#include <stddef.h>
#include <stdio.h>

#include "graph.h"

/* ------------------------------------------------------------------ */
/*  Traversal with callbacks */
/* ------------------------------------------------------------------ */

/**
 * graph_bfs_visit / graph_dfs_visit - traverse from @start, calling @fn per
 * vertex.  DFS is iterative pre-order.  No output arrays are needed, so memory
 * is O(N) bits plus the frontier.  Returns the number of vertices visited
 * (0 if @start is not alive or @fn is NULL).  Complexity: O(V + E + N * V / 64).
 */
size_t graph_bfs_visit(Graph *g, int start, GraphVisitFn fn, void *ctx);

size_t graph_dfs_visit(Graph *g, int start, GraphVisitFn fn, void *ctx);

/* ------------------------------------------------------------------ */
/*  Structure and analysis */
/* ------------------------------------------------------------------ */

/** Out-degree / (V - 1).  out: N entries. */
GraphStatus graph_degree_centrality(Graph *g, double *out);

/**
 * Closeness by hop count, Wasserman-Faust normalised so disconnected graphs
 * work: (r / (V - 1)) * (r / sum_of_distances), r = vertices reachable from v.
 * 0 for an isolated vertex.  Complexity: O(V * (V + E)).
 */
GraphStatus graph_closeness_centrality(Graph *g, double *out);

/**
 * Betweenness (Brandes), unweighted shortest paths.  Raw pair counts; for an
 * undirected graph each pair is counted once.  Complexity: O(V * (V + E)).
 */
GraphStatus graph_betweenness_centrality(Graph *g, double *out);

/** Number of triangles.  Undirected only.  Complexity: O(sum of degree^2). */
GraphStatus graph_triangle_count(Graph *g, long long *total);

/**
 * Local clustering coefficient per vertex (0 when degree < 2) and/or the
 * average over alive vertices (zeros included).  Either output may be NULL.
 * Undirected only.
 */
GraphStatus graph_clustering_coefficient(Graph *g, double *local, double *average);

/**
 * 2-colourability of the underlying undirected graph.  @color (optional, N
 * entries) receives 0/1, or -1 for dead IDs; it is only meaningful if *result.
 */
GraphStatus graph_is_bipartite(Graph *g, bool *result, int *color);

/** Largest hop distance from each vertex to a vertex it can reach.  N entries. */
GraphStatus graph_eccentricity(Graph *g, int *ecc);

/**
 * Diameter and radius in hops.  GRAPH_ERR_UNSUPPORTED if some vertex cannot
 * reach another (not connected / not strongly connected); INVALID if empty.
 */
GraphStatus graph_diameter_radius(Graph *g, int *diameter, int *radius);

/** Common out-neighbours of u and v, ascending.  out: N entries. */
GraphStatus graph_common_neighbors(Graph *g, int u, int v, int *out, size_t *count);

/** |N(u) ∩ N(v)| / |N(u) ∪ N(v)| over out-neighbours; 0 when both are empty. */
GraphStatus graph_jaccard(Graph *g, int u, int v, double *score);

GraphStatus graph_network_stats(Graph *g, GraphNetworkStats *out);

/** hist[d] = number of vertices with out-degree d; degrees >= len-1 land in hist[len-1]. */
GraphStatus graph_degree_histogram(Graph *g, size_t *hist, size_t len);

bool graph_is_connected(Graph *g);

bool graph_is_strongly_connected(Graph *g);

bool graph_is_dag(Graph *g);

bool graph_is_tree(Graph *g);

bool graph_is_forest(Graph *g);

/**
 * Strongly connected components (Tarjan, iterative).  component: N entries,
 * numbered in reverse topological order of the condensation (component 0 has
 * no outgoing edges to other components).  Undirected graphs get their
 * ordinary components.  *count (optional) receives the number of components.
 */
GraphStatus graph_strongly_connected_components(Graph *g, int *component, size_t *count);

/** Undirected only.  is_cut: N entries; *count (optional) = number of cut vertices. */
GraphStatus graph_articulation_points(Graph *g, bool *is_cut, size_t *count);

/** Undirected only.  out needs graph_graph_edge_count() entries; *count = bridges found. */
GraphStatus graph_bridges(Graph *g, GraphEdge *out, size_t *count);

/**
 * Biconnected components, undirected only.  Each group is the vertex set of
 * one block (an articulation point appears in every block it joins).
 * Isolated vertices belong to no block.  Free with graph_groups_free.
 */
GraphStatus graph_biconnected_components(Graph *g, GraphGroups *out);

/**
 * Find a cycle.  Writes its vertices in order into @cycle (the last connects
 * back to the first) and returns its length; 0 if the graph is acyclic.  A
 * self-loop is a cycle of length 1.  @cycle needs graph_graph_vertex_count()
 * entries.  Complexity: O(V + E).
 */
size_t graph_find_cycle(Graph *g, int *cycle);

/* ------------------------------------------------------------------ */
/*  Shortest paths */
/* ------------------------------------------------------------------ */

/**
 * Bellman-Ford; handles negative weights.  distance/parent: N entries
 * (INFINITY / -1 when unreachable).  GRAPH_ERR_NEGATIVE_CYCLE if one is
 * reachable from @src (any negative undirected edge is a negative cycle).
 * Complexity: O(V * (V + E)).
 */
GraphStatus graph_bellman_ford(Graph *g, int src, double *distance, int *parent);

/**
 * All-pairs shortest paths.  distance and next (optional) are N*N row-major
 * arrays: distance[u*N+v], next[u*N+v] = first hop after u on a shortest path
 * to v (-1 if none).  distance[u*N+u] = 0.  GRAPH_ERR_TOO_LARGE if N > 8192.
 * Complexity: O(V^3).
 */
GraphStatus graph_floyd_warshall(Graph *g, double *distance, int *next);

/**
 * All-pairs shortest paths for sparse graphs with negative weights (Johnson):
 * Bellman-Ford once, then Dijkstra from every vertex.  Same output layout as
 * graph_floyd_warshall.  Complexity: O(V * (V + E) log V).
 */
GraphStatus graph_johnson(Graph *g, double *distance, int *next);

/**
 * A* from @src to @dst.  @h may be NULL (then this is Dijkstra).  Weights must
 * be non-negative.  On success @out (allocated; graph_path_free) holds the
 * path.  GRAPH_ERR_NOT_FOUND if @dst is unreachable.  An admissible heuristic
 * gives an optimal path even if it is not consistent.
 */
GraphStatus graph_a_star(Graph *g, int src, int dst, GraphHeuristic h, void *ctx, GraphPath *out);

/**
 * Dijkstra from several sources at once: distance to the nearest source.
 * @origin (optional, N entries) = which source that is.  Non-negative weights.
 */
GraphStatus graph_dijkstra_multi(Graph *g, const int *sources, size_t count, double *distance, int *parent, int *origin);

/** Shortest paths when every weight is 0 or 1 (else INVALID_ARGUMENT).  O(V + E). */
GraphStatus graph_zero_one_bfs(Graph *g, int src, double *distance, int *parent);

/**
 * Up to @k shortest loopless src -> dst paths in non-decreasing cost (Yen).
 * @paths: k entries, the first *found of which are filled (each freed with
 * graph_path_free).  Non-negative weights.  GRAPH_ERR_NOT_FOUND if no path.
 */
GraphStatus graph_k_shortest_paths(Graph *g, int src, int dst, size_t k, GraphPath *paths, size_t *found);

/* ------------------------------------------------------------------ */
/*  Spanning trees, flow, matching */
/* ------------------------------------------------------------------ */

/**
 * Prim's MST with a binary heap, O(E log V).  Same contract as graph_mst_kruskal:
 * @edges needs vertex_count - 1 entries; returns the total weight, INFINITY if
 * the graph is directed or disconnected.
 */
double graph_mst_prim(Graph *g, GraphEdge *edges, size_t *edge_count);

/**
 * Maximum flow from @source to @sink; edge weights are capacities (must be
 * >= 0).  An undirected edge carries flow either way.  *value receives the
 * flow; @source_side (optional, N entries) marks the source side of a minimum
 * cut.  Dinic: O(V^2 E); Edmonds-Karp: O(V E^2).
 */
GraphStatus graph_max_flow(Graph *g, int source, int sink, GraphFlowAlgo algo, double *value, bool *source_side);

/**
 * Minimum source-sink cut.  *value = cut capacity; @cut (needs edge_count
 * entries) lists the edges leaving the source side; *count = how many.
 */
GraphStatus graph_min_cut(Graph *g, int source, int sink, double *value, GraphEdge *cut, size_t *count);

/**
 * Maximum cardinality matching in a bipartite graph (Hopcroft-Karp), O(E sqrt(V)).
 * match: N entries, match[v] = partner or -1.  *size = number of matched pairs.
 * GRAPH_ERR_UNSUPPORTED if the graph is not bipartite.
 */
GraphStatus graph_bipartite_matching(Graph *g, int *match, size_t *size);

/* ------------------------------------------------------------------ */
/*  Combinatorial */
/* ------------------------------------------------------------------ */

/**
 * Euler trail that uses every edge once.  If @closed, a circuit is required.
 * @path needs edge_count + 1 entries; *length = edge_count + 1 (0 for a graph
 * with no edges).  GRAPH_ERR_NOT_FOUND if none exists.  Complexity: O(V + E).
 */
GraphStatus graph_euler_trail(Graph *g, bool closed, int *path, size_t *length);

/**
 * Hamiltonian path (or cycle) by bitmask DP.  At most 24 alive vertices
 * (else TOO_LARGE).  @path needs vertex_count entries.  NOT_FOUND if none.
 * A cycle needs at least 3 vertices (2 if directed).  Complexity: O(2^V V^2).
 */
GraphStatus graph_hamiltonian(Graph *g, bool cycle, int *path);

/**
 * Proper vertex colouring of the underlying undirected graph; colours start at
 * 0.  color: N entries (-1 for dead).  *ncolors (optional) = colours used.
 * Greedy visits vertices in ascending ID; Welsh-Powell by descending degree;
 * DSatur by saturation (usually fewest colours).
 */
GraphStatus graph_color_greedy(Graph *g, int *color, size_t *ncolors);

GraphStatus graph_color_welsh_powell(Graph *g, int *color, size_t *ncolors);

GraphStatus graph_color_dsatur(Graph *g, int *color, size_t *ncolors);

/**
 * All maximal cliques (Bron-Kerbosch with pivoting), undirected only.  Output
 * size can be exponential.  Free with graph_groups_free.
 */
GraphStatus graph_maximal_cliques(Graph *g, GraphGroups *out);

/** A largest clique.  @clique needs vertex_count entries; *size = its size. */
GraphStatus graph_max_clique(Graph *g, int *clique, size_t *size);

/** 2-approximate vertex cover (maximal matching).  in_cover: N entries. */
GraphStatus graph_vertex_cover_approx(Graph *g, bool *in_cover, size_t *size);

/** Greedy maximal independent set (lowest degree first).  in_set: N entries. */
GraphStatus graph_independent_set_greedy(Graph *g, bool *in_set, size_t *size);

/**
 * Longest weighted path in a DAG.  distance[v] = longest path ending at v
 * (>= 0, a single vertex is a path; dead IDs get -INFINITY); parent: N entries;
 * *end = the vertex with the largest distance (-1 if the graph is empty).
 * GRAPH_ERR_UNSUPPORTED if undirected or cyclic.
 */
GraphStatus graph_dag_longest_path(Graph *g, double *distance, int *parent, int *end);

/** The critical path itself.  @path needs vertex_count entries. */
GraphStatus graph_critical_path(Graph *g, int *path, size_t *length, double *cost);

/* ------------------------------------------------------------------ */
/*  Network analysis */
/* ------------------------------------------------------------------ */

/**
 * PageRank by power iteration.  Edge weights (>= 0) are transition weights;
 * dangling vertices spread rank evenly.  out sums to 1 over alive vertices.
 * *iterations (optional) = rounds used.  GRAPH_ERR_NO_CONVERGENCE if the L1
 * change stays above @tolerance after @max_iterations (out still holds the
 * latest estimate).
 */
GraphStatus graph_pagerank(Graph *g, double damping, double tolerance, size_t max_iterations, double *out, size_t *iterations);

/** HITS hub and authority scores, each L2-normalised. */
GraphStatus graph_hits(Graph *g, double tolerance, size_t max_iterations, double *hub, double *authority);

/** Eigenvector centrality (in-edges for directed graphs), L2-normalised. */
GraphStatus graph_eigenvector_centrality(Graph *g, double tolerance, size_t max_iterations, double *out);

/** Core number of each vertex (k-core decomposition) of the underlying undirected graph. */
GraphStatus graph_core_numbers(Graph *g, int *core);

/**
 * Community detection by label propagation, deterministic (ascending vertex
 * order, ties to the smaller label).  community: N entries numbered 0.. by
 * first appearance; *count (optional) = number of communities.
 */
GraphStatus graph_label_propagation(Graph *g, int *community, size_t *count);

/**
 * Louvain modularity optimisation on the underlying undirected graph (edge
 * weights must be >= 0; self-loops are ignored).  community: N entries (-1 for
 * dead IDs); *modularity (optional) and *count (optional) describe the result.
 * Deterministic: vertices are visited in ascending ID order.
 */
GraphStatus graph_louvain(Graph *g, int *community, double *modularity, size_t *count);

/** Modularity of a given partition (community has N entries, -1 for dead IDs). */
GraphStatus graph_modularity(Graph *g, const int *community, double *q);

/** Newman's degree assortativity.  UNSUPPORTED if undefined (e.g. a regular graph). */
GraphStatus graph_degree_assortativity(Graph *g, double *r);

/* ------------------------------------------------------------------ */
/*  Graph operations */
/* ------------------------------------------------------------------ */

/* ------------------------------------------------------------------ */
/*  Generators (deterministic for a given seed) */
/* ------------------------------------------------------------------ */

/* ------------------------------------------------------------------ */
/*  Input / output */
/* ------------------------------------------------------------------ */

/**
 * Graphviz DOT.  @labels (optional, N entries, may contain NULLs) names the
 * vertices; @show_weights prints edge weights.  Dead IDs are omitted.
 */
GraphStatus graph_write_dot(Graph *g, FILE *out, const char *name, const char *const *labels, bool show_weights);

GraphStatus graph_write_edge_list(Graph *g, FILE *out);

/** Compact binary snapshot: keeps IDs, dead IDs, direction and weights exactly. */
GraphStatus graph_save_binary(Graph *g, FILE *out);

/** Export-only formats. */
GraphStatus graph_write_graphml(Graph *g, FILE *out);

GraphStatus graph_write_gml(Graph *g, FILE *out);

GraphStatus graph_write_json(Graph *g, FILE *out);

/* ------------------------------------------------------------------ */
/*  Functions that build or combine graphs (src/graph_build.c)          */
/*                                                                      */
/*  Every graph handed back is a new Graph the caller must free with    */
/*  graph_destroy.  Results are created in the same representation as   */
/*  the input graph (generators take the representation explicitly).    */
/*  On failure *out is set to NULL and a GraphStatus is returned.       */
/* ------------------------------------------------------------------ */

GraphStatus graph_transpose(Graph *g, Graph **out);
GraphStatus graph_transitive_closure(Graph *g, Graph **out);
GraphStatus graph_transitive_reduction(Graph *g, Graph **out);
GraphStatus graph_induced_subgraph(Graph *g, const int *vertices, size_t count, Graph **out);
GraphStatus graph_complement(Graph *g, Graph **out);

/** Deep copy (same representation).  NULL on failure; see graph_last_error(). */
Graph *graph_copy(Graph *g);

/** @a and @b must both be directed or both undirected.  @b is converted
 *  temporarily if it uses the other representation. */
GraphStatus graph_union(Graph *a, Graph *b, Graph **out);
GraphStatus graph_intersection(Graph *a, Graph *b, Graph **out);
GraphStatus graph_is_isomorphic(Graph *a, Graph *b, bool *result, int *mapping);

/* Generators: parameters as in list_gen_* / matrix_gen_*, plus the representation
 * to start in.  NULL on failure; see graph_last_error(). */
Graph *graph_gen_erdos_renyi(GraphRep rep, size_t n, double p, unsigned long long seed,
                             bool directed, double wmin, double wmax);
Graph *graph_gen_barabasi_albert(GraphRep rep, size_t n, size_t m, unsigned long long seed);
Graph *graph_gen_grid(GraphRep rep, size_t rows, size_t cols);
Graph *graph_gen_path(GraphRep rep, size_t n, bool directed);
Graph *graph_gen_cycle(GraphRep rep, size_t n, bool directed);
Graph *graph_gen_star(GraphRep rep, size_t n);
Graph *graph_gen_complete(GraphRep rep, size_t n, bool directed);
Graph *graph_gen_random_dag(GraphRep rep, size_t n, double p, unsigned long long seed,
                            double wmin, double wmax);
Graph *graph_gen_random_tree(GraphRep rep, size_t n, unsigned long long seed);

/* Readers: the graph is created in representation @rep. */
GraphStatus graph_read_edge_list(FILE *in, bool directed, GraphRep rep, Graph **out);
GraphStatus graph_read_named_edge_list(FILE *in, bool directed, GraphRep rep, Graph **out,
                                       char ***names_out, size_t *count);
GraphStatus graph_load_binary(FILE *in, GraphRep rep, Graph **out);
void        graph_names_free(char **names, size_t count);

/* Representation-independent helpers (they do not take a graph). */
GraphStatus graph_hungarian(const double *cost, size_t rows, size_t cols,
                            int *assignment, double *total);
size_t graph_path_from_parent(const int *parent, size_t n, int src, int dst, int *path, size_t cap);
size_t graph_path_from_next(const int *next, size_t n, int u, int v, int *path, size_t cap);

#endif /* GRAPH_ALGORITHMS_H */
